<?php
declare(strict_types=1);
namespace Babanoell\Panel\Contracts;
use Babanoell\Panel\Http\PartnersClient;use Babanoell\Panel\Http\DocumentsClient;use Babanoell\Panel\Security\Csrf;use Babanoell\Panel\Support\PersianDateTime;use Babanoell\Panel\View\Renderer;
final class ContractsModule
{
 public function __construct(private readonly PartnersClient $partners,private readonly string $bearer,private readonly array $identity,private readonly ?DocumentsClient $documents=null){}
 public function handle(string $path,string $method):bool{
  if(preg_match('#^/contracts/(loan|cooperation)/([a-f0-9]{26})$#',$path,$m)){if($method==='POST')$this->create($m[1],$m[2]);else $this->subject($m[1],$m[2]);return true;}
  if(preg_match('#^/contracts/([a-f0-9]{26})/pdf$#',$path,$m)&&$method==='GET'){$this->downloadPdf($m[1]);return true;}
  if(preg_match('#^/contracts/([a-f0-9]{26})/print$#',$path,$m)&&$method==='GET'){$this->printContract($m[1]);return true;}
  if(preg_match('#^/contracts/([a-f0-9]{26})$#',$path,$m)&&$method==='GET'){$this->detail($m[1]);return true;}
  if(preg_match('#^/contracts/([a-f0-9]{26})/(issue-link|sign-physical|artifact-retry|reissue|open-signing)$#',$path,$m)&&$method==='POST'){$this->action($m[1],$m[2]);return true;}
  return false;
 }
 private function subject(string$type,string$id):void{
  $api=$type==='loan'?'/api/v1/loan-requests/'.$id.'/contracts':'/api/v1/cooperation/requests/'.$id.'/contracts';$r=$this->partners->get($api,$this->bearer);if(!$r->ok()){$this->error('قراردادها',$r->json['error']['message']??'دریافت قراردادها انجام نشد.');return;}$items=(array)($r->json['data']['items']??[]);$rows='';foreach($items as$c){if(!is_array($c))continue;$rows.='<tr><td><a href="/contracts/'.Renderer::e((string)$c['id']).'">'.Renderer::e((string)$c['contract_no']).'</a></td><td>'.Renderer::e($this->kind((string)$c['contract_kind'])).'</td><td>'.(int)($c['revision']??1).'</td><td>'.Renderer::e((string)$c['mode']==='digital'?'دیجیتال':'فیزیکی').'</td><td>'.Renderer::e($this->status((string)$c['status'])).'</td><td>'.Renderer::e((string)($c['artifact_status']??'—')).'</td></tr>';}$rows=$rows?:'<tr><td colspan="6">قراردادی ثبت نشده است.</td></tr>';
  $kindFields=$type==='loan'?'<div class="bn-field"><label class="bn-label">نوع قرارداد</label><select name="contract_kind"><option value="loan_application">درخواست تسهیلات</option><option value="facility_agreement">قرارداد دریافت تسهیلات</option></select></div>':'<input type="hidden" name="contract_kind" value="cooperation_agreement"><div class="bn-field"><label class="bn-label">نوع قرارداد</label><input value="قرارداد همکاری" readonly></div>';
  $content=$this->head('قراردادها','نسخه قرارداد در زمان ایجاد منجمد و هش می‌شود.').$this->flash().'<section class="bn-section"><div class="bn-table-wrap"><table class="bn-table"><thead><tr><th>شماره</th><th>نوع</th><th>نسخه</th><th>حالت</th><th>وضعیت</th><th>فایل نهایی</th></tr></thead><tbody>'.$rows.'</tbody></table></div></section>';
  if($this->canManageType($type))$content.='<section class="bn-section"><h2 class="bn-sectiontitle">ایجاد قرارداد</h2><form method="post"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><div class="bn-grid bn-grid--2">'.$kindFields.'<div class="bn-field"><label class="bn-label">حالت</label><select name="mode"><option value="digital">دیجیتال</option><option value="physical">فیزیکی</option></select></div></div><button class="bn-btn bn-btn--primary">ایجاد قرارداد</button></form></section>';
  else $content.='<p class="bn-helper">آماده‌سازی و صدور قرارداد توسط کاربر مسئول انجام می‌شود. وضعیت نسخه‌ها از همین صفحه قابل پیگیری است.</p>';
  echo Renderer::page('قراردادها',$content,$this->identity,'contracts');
 }
 private function create(string$type,string$id):void{if(!Csrf::valid((string)($_POST['_csrf']??''))){$this->setFlash('error','اعتبار فرم منقضی شده است.');$this->go('/contracts/'.$type.'/'.$id);} $api=$type==='loan'?'/api/v1/loan-requests/'.$id.'/contracts':'/api/v1/cooperation/requests/'.$id.'/contracts';$payload=['contract_kind'=>(string)($_POST['contract_kind']??($type==='loan'?'facility_agreement':'cooperation_agreement')),'mode'=>(string)($_POST['mode']??'digital')];$r=$this->partners->post($api,$this->bearer,$payload);$this->setFlash($r->ok()?'success':'error',$r->ok()?'قرارداد ایجاد شد.':(string)($r->json['error']['message']??'ایجاد قرارداد انجام نشد.'));$this->go('/contracts/'.$type.'/'.$id);}
 private function detail(string$id):void{$r=$this->partners->get('/api/v1/contracts/'.$id,$this->bearer);if(!$r->ok()){$this->error('قرارداد','قرارداد پیدا نشد.');return;}$c=(array)($r->json['data']['contract']??[]);$events=(array)($r->json['data']['events']??[]);$eventRows='';foreach($events as$e){if(!is_array($e))continue;$eventRows.='<tr><td>'.Renderer::e((string)($e['event_type']??'')).'</td><td>'.Renderer::e((string)($e['result']??'')).'</td><td>'.Renderer::e(PersianDateTime::fromIso((string)($e['created_at']??''),false)??'—').'</td></tr>';}$eventRows=$eventRows?:'<tr><td colspan="3">رویدادی ثبت نشده است.</td></tr>';$content=$this->head('قرارداد '.(string)($c['contract_no']??''),'وضعیت: '.$this->status((string)($c['status']??''))).$this->flash().'<div class="bn-detail-grid">'.$this->detailItem('نوع',$this->kind((string)($c['contract_kind']??''))).$this->detailItem('نسخه',(string)($c['revision']??1)).$this->detailItem('حالت',(string)($c['mode']??'')==='digital'?'دیجیتال':'فیزیکی').$this->detailItem('قالب',(string)($c['template_code']??'—').' v'.(string)($c['template_version']??'')).$this->detailItem('هش محتوا',substr((string)($c['rendered_hash']??''),0,24)).$this->detailItem('زمان امضا',(string)($c['signed_at']??'—')).$this->detailItem('Artifact',(string)($c['artifact_status']??'—')).($c['reissue_reason']??null?$this->detailItem('علت بازصدور',(string)$c['reissue_reason']):'').'</div><section class="bn-section"><h2 class="bn-sectiontitle">متن قرارداد</h2><div class="bn-prose">'.(string)($c['rendered_content']??'').'</div></section><section class="bn-section"><div class="bn-form-actions">';
  if(($c['subject_type']??'')==='cooperation_request'&&($c['signer_user_id']??'')===($this->identity['user']['id']??'')&&($c['mode']??'')==='digital'&&in_array($c['status'],['pending','sent','viewed'],true))$content.='<form method="post" action="/contracts/'.$id.'/open-signing"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><button class="bn-btn bn-btn--primary">مشاهده و امضای قرارداد</button></form>';
  if($this->canManageType((string)($c['subject_type']??''))&&(string)($c['status']??'')!=='signed'&&(string)($c['status']??'')!=='cancelled')$content.='<form method="post" action="/contracts/'.$id.'/issue-link"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><button class="bn-btn bn-btn--primary">صدور لینک امن</button></form>';
  if($this->canManageType((string)($c['subject_type']??''))&&(string)($c['mode']??'')==='physical'&&(string)($c['status']??'')!=='signed')$content.='<form method="post" action="/contracts/'.$id.'/sign-physical"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><button class="bn-btn bn-btn--secondary">ثبت امضای فیزیکی</button></form>';
  if($this->canManageType((string)($c['subject_type']??''))&&(string)($c['status']??'')==='signed'&&(string)($c['artifact_status']??'')!=='stored')$content.='<form method="post" action="/contracts/'.$id.'/artifact-retry"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><button class="bn-btn bn-btn--secondary">تلاش مجدد ذخیره Artifact</button></form>';
  if(($c['status']??'')==='signed') {
   if(preg_match('/^[a-f0-9]{26}$/',(string)($c['pdf_document_id']??'')))$content.='<a class="bn-btn bn-btn--primary" href="/contracts/'.$id.'/pdf">دریافت PDF امضاشده</a>';
   elseif($this->canManageType((string)($c['subject_type']??''))) $content.='<span class="bn-alert">PDF نهایی هنوز تولید نشده است؛ نصب موتور PDF یا تلاش مجدد ذخیره سند لازم است.</span><form method="post" action="/contracts/'.$id.'/artifact-retry"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><button class="bn-btn bn-btn--secondary">تلاش مجدد تولید PDF</button></form>';
  }
  $content.='<a class="bn-btn bn-btn--secondary" href="/contracts/'.$id.'/print" target="_blank" rel="noopener">نمایش نسخه چاپی</a></div></section>';
  if($this->canManageType((string)($c['subject_type']??''))&&in_array((string)($c['status']??''),['signed','pending','viewed','sent'],true))$content.='<section class="bn-section"><h2 class="bn-sectiontitle">بازصدور قرارداد</h2><p>نسخه امضاشده قبلی و گواهی آن دست‌نخورده می‌ماند؛ بازصدور نیازمند امضای مستقل نسخه جدید است.</p><form method="post" action="/contracts/'.$id.'/reissue"><input type="hidden" name="_csrf" value="'.Renderer::e(Csrf::token()).'"><input type="hidden" name="row_version" value="'.(int)($c['row_version']??1).'"><div class="bn-field"><label class="bn-label">دلیل بازصدور</label><textarea name="reason" rows="2" minlength="10" maxlength="1000" required></textarea></div><div class="bn-field"><label class="bn-label">حالت نسخه جدید</label><select name="mode"><option value="'.Renderer::e((string)($c['mode']??'digital')).'">حفظ حالت فعلی</option><option value="digital">دیجیتال</option><option value="physical">فیزیکی</option></select></div><div class="bn-field"><label class="bn-label">متن HTML جدید (اختیاری، خالی یعنی کپی متن نسخه فعلی)</label><textarea name="content_html" rows="5" placeholder="برای حفظ متن نسخه قبل، این کادر را خالی بگذارید"></textarea></div><button class="bn-btn bn-btn--primary" type="submit">ایجاد نسخه جدید مستقل</button></form></section>';
  $content.='<section class="bn-section"><h2 class="bn-sectiontitle">Audit قرارداد</h2><div class="bn-table-wrap"><table class="bn-table"><thead><tr><th>رویداد</th><th>نتیجه</th><th>زمان</th></tr></thead><tbody>'.$eventRows.'</tbody></table></div></section>';echo Renderer::page('قرارداد',$content,$this->identity,'contracts');}
 private function action(string$id,string$action):void{if(!Csrf::valid((string)($_POST['_csrf']??''))){$this->setFlash('error','اعتبار فرم منقضی شده است.');$this->go('/contracts/'.$id);} $endpoint=match($action){'issue-link'=>'issue-link','sign-physical'=>'sign-physical','artifact-retry'=>'artifact/retry','reissue'=>'reissue','open-signing'=>'signing-link'};$payload=[];if($action==='reissue'){$payload=['reason'=>trim((string)($_POST['reason']??'')),'row_version'=>(int)($_POST['row_version']??0),'mode'=>(string)($_POST['mode']??'')];$html=trim((string)($_POST['content_html']??''));if($html!=='')$payload['content_html']=$html;}$r=$this->partners->post('/api/v1/contracts/'.$id.'/'.$endpoint,$this->bearer,$payload);if($r->ok()&&$action==='open-signing'){$path=(string)($r->json['data']['public_path']??'');if(preg_match('#^/contract/[A-Za-z0-9_-]{30,120}$#D',$path)){header('Location:'.$this->partners->absolute($path),true,303);exit;}} if($r->ok()&&$action==='reissue'){$newId=(string)($r->json['data']['contract']['id']??'');$this->setFlash('success','نسخه جدید قرارداد ساخته شد؛ برای امضا باید لینک مستقل صادر شود.');if(preg_match('/^[a-f0-9]{26}$/',$newId))$this->go('/contracts/'.$newId);}
  if($r->ok()&&$action==='issue-link'){$path=(string)($r->json['data']['public_path']??'');$url=$path!==''?$this->partners->absolute($path):'';$this->setFlash('success',$url!==''?'لینک امن: '.$url:'لینک امن صادر شد.');}else $this->setFlash($r->ok()?'success':'error',$r->ok()?'عملیات انجام شد.':(string)($r->json['error']['message']??'عملیات انجام نشد.'));$this->go('/contracts/'.$id);}
 private function downloadPdf(string $id):void
 {
  $r=$this->partners->get('/api/v1/contracts/'.$id,$this->bearer);
  if(!$r->ok()){http_response_code(403);echo 'دسترسی به قرارداد مجاز نیست.';return;}
  $contract=(array)($r->json['data']['contract']??[]);$documentId=(string)($contract['pdf_document_id']??'');
  if(($contract['status']??'')!=='signed'||!preg_match('/^[a-f0-9]{26}$/',$documentId)||$this->documents===null){http_response_code(404);echo 'نسخه PDF امضاشده موجود نیست.';return;}
  $access=$this->documents->post('/api/v1/files/'.$documentId.'/access-token',$this->bearer,['purpose'=>'download']);
  $path=(string)($access->json['data']['path']??'');
  if(!$access->ok()||!preg_match('#^/api/v1/access/download/[A-Za-z0-9_-]{30,120}$#',$path)){http_response_code(403);echo 'مجوز دریافت PDF صادر نشد.';return;}
  header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');
  header('Location: '.$this->documents->absolute($path),true,303);exit;
 }
 private function printContract(string $id):void{
  $r=$this->partners->get('/api/v1/contracts/'.$id,$this->bearer);
  if(!$r->ok()){http_response_code(403);echo 'دسترسی به سند مجاز نیست.';return;}
  $c=(array)($r->json['data']['contract']??[]);
  header('Content-Type:text/html;charset=utf-8');header('Cache-Control:private,no-store,max-age=0');header('X-Frame-Options:DENY');header('Referrer-Policy:no-referrer');header('X-Content-Type-Options:nosniff');header("Content-Security-Policy: default-src 'none'; script-src 'none'; style-src 'unsafe-inline'; img-src 'self' https: data:; font-src 'self' data:; base-uri 'none'; frame-ancestors 'none'");
  $rendered=(string)($c['rendered_content']??'');$no=Renderer::e((string)($c['contract_no']??''));$hash=Renderer::e((string)($c['rendered_hash']??''));$revision=(int)($c['revision']??1);
  echo '<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>چاپ قرارداد '.$no.'</title><style>@page{size:A4;margin:17mm 15mm 19mm}body{font:13px/1.95 Tahoma,Arial,sans-serif;color:#182434;margin:20px auto;max-width:180mm}.head{border-bottom:2px solid #1D3559;display:flex;justify-content:space-between;padding:10px 0;margin-bottom:18px}.doc p{margin:0 0 10px}.doc table{width:100%;border-collapse:collapse}.doc td,.doc th{border:1px solid #aaa;padding:6px}.doc img{max-width:100%}.doc p,.doc table,section{break-inside:avoid-page}.foot{border-top:1px solid #aaa;margin-top:25px;padding-top:12px;overflow-wrap:anywhere;font-size:10px}@media print{body{margin:0;max-width:none}}</style></head><body><header class="head"><strong>پلتفرم اعتباری نوئل</strong><span>'.$no.' | نسخه '.$revision.'</span></header><div class="doc">'.$rendered.'</div><section class="foot">وضعیت: '.Renderer::e((string)($c['status']??'')).' | امضا: '.Renderer::e((string)($c['signed_at']??'—')).'<p>SHA-256: '.$hash.'</p></section></body></html>';
 }
 private function kind(string$k):string{return['cooperation_agreement'=>'قرارداد همکاری','loan_application'=>'درخواست تسهیلات','facility_agreement'=>'قرارداد دریافت تسهیلات'][$k]??$k;}
 private function canManageType(string$type):bool{$roles=(array)($this->identity['roles']??[]);$permissions=(array)($this->identity['permissions']??[]);if(in_array('super_admin',$roles,true))return true;$permission=in_array($type,['loan','loan_request'],true)?'loans.requests.contract':(in_array($type,['cooperation','cooperation_request'],true)?'partners.cooperation.manage':'');return $permission!==''&&in_array($permission,$permissions,true);}
 private function status(string$s):string{return['pending'=>'در انتظار','sent'=>'ارسال‌شده','viewed'=>'مشاهده‌شده','otp_verified'=>'OTP تأییدشده','signed'=>'امضاشده','expired'=>'منقضی','cancelled'=>'لغوشده','legacy_imported'=>'مهاجرتی'][$s]??$s;}
 private function detailItem(string$l,string$v):string{return'<div class="bn-detail-item"><span>'.Renderer::e($l).'</span><strong>'.Renderer::e($v).'</strong></div>';}
 private function head(string$t,string$s):string{return'<div class="bn-pagehead"><div class="bn-pagehead-main"><div class="bn-eyebrow">Contract Engine</div><h1 class="bn-title">'.Renderer::e($t).'</h1><p class="bn-subtitle">'.Renderer::e($s).'</p></div></div>';}
 private function setFlash(string$t,string$m):void{$_SESSION['contract_flash']=['type'=>$t,'message'=>$m];}
 private function flash():string{$f=$_SESSION['contract_flash']??null;unset($_SESSION['contract_flash']);if(!is_array($f))return'';return'<div class="bn-alert bn-alert--'.(($f['type']??'')==='success'?'success':'error').'"><strong>'.Renderer::e((string)($f['message']??'')).'</strong></div>';}
 private function error(string$t,string$m):void{http_response_code(503);echo Renderer::page($t,$this->head($t,$m),$this->identity,'contracts');}
 private function go(string$p):never{header('Location: '.$p,true,303);exit;}
}
